__device__ __forceinline__ bool vit_is_muon_2d(int t) {
    if (t == 1 || t == 3) return true;
    if (t == 4 + 12 * vit::kLayers + 2) return true;       // head out.weight
    if (t >= 4 && t < 4 + 12 * vit::kLayers) {
